<template><main class="ccd-page members-page"><ConnectedDemoHeader icon="♙" title="Connected Members" subtitle="Understand participation across Twitch, Discord and Project Respawn."/><div class="privacy-banner">🔒 Privacy first: We only show data members have chosen to share. Confidence reflects data quality, not personal tracking. <b>Learn more</b></div><div class="ccd-tabs"><button v-for="item in filters" :key="item" class="ccd-tab" :class="{active:filter===item}" @click="filter=item">{{item}}</button></div><section class="members-layout"><section class="ccd-card member-list"><div class="member-search"><label><span class="ccd-sr">Search members</span><input v-model="query" placeholder="⌕  Search members…"></label><button class="ccd-button">▽</button></div><div class="member-head"><span>Member</span><span>Platforms</span><span>Status</span><span>Tier</span></div><button v-for="member in shownMembers" :key="member.id" :class="{active:demo.selectedMemberId===member.id}" @click="selectDemoMember(member.id)"><span class="avatar">{{member.name[0]}}</span><span><b>{{member.name}}</b><small>{{member.handle}}</small></span><span class="platform-icons">{{member.platforms}}</span><span :class="member.status==='Online'?'ccd-positive':'status-idle'">● {{member.status}}</span><span>{{member.tier}}</span></button><footer>1–{{shownMembers.length}} of 842 members <span><button>‹</button><button class="active">1</button><button>2</button><button>3</button><button>›</button></span></footer></section><section class="member-detail"><section class="ccd-card identity-card"><div class="nova-avatar">N</div><div><h2>{{selected.name}}</h2><span class="connected-pill">♢ Connected Member</span><div class="identities"><span v-for="identity in selectedIdentities" :key="identity.platform"><i>{{icon(identity.platform)}}</i><b>{{identity.label}}</b><small>{{identity.handle}}　<span class="ccd-positive">✓</span></small></span></div></div></section><section class="ccd-card privacy-cards"><article><h3>Data Confidence ⓘ</h3><div class="confidence">{{selected.id==='member-nova'?'96':'88'}}%</div><b class="ccd-positive">High</b></article><article><h3>Consent &amp; Privacy</h3><p>✓ Data shared with consent</p><p>✓ Profile visible to community</p><p>✓ Analytics participation</p><b class="ccd-purple">Open privacy controls</b></article></section><nav class="profile-tabs"><button class="active">Overview</button><button>Activity</button><button>Events</button><button>Rewards</button><button>Achievements</button><button>Moderation</button></nav><section class="ccd-card member-metrics"><article><span>♙</span><small>Community contribution</small><strong>+{{demo.nova.contribution}}</strong><p>vs last 30 days ↑</p></article><article><span>▣</span><small>Member since</small><strong>7</strong><p>months</p></article><article><span>🎟</span><small>Events attended</small><strong>{{demo.nova.eventsAttended}}</strong><p>All time</p></article><article><span>★</span><small>Points earned</small><strong>{{demo.nova.balance.toLocaleString()}}</strong><p>All time</p></article><article><span>⬡</span><small>Supporter tier</small><strong>Bronze</strong><p>Since Apr 5, 2024</p></article><article><span>🏆</span><small>Achievements</small><strong>{{demo.nova.achievements}}</strong><p>of 28</p></article></section><section class="member-detail-grid"><article class="ccd-card timeline"><h3>Timeline</h3><ul class="ccd-list"><li v-for="item in demo.activity.slice(0,6)" :key="item.id"><span>{{item.icon}}</span><div><b>{{item.title}}</b><small>{{item.detail}}</small></div></li></ul></article><article class="ccd-card"><h3>Recent Events <small>View all</small></h3><ul class="media-list"><li><span>🎮</span><div><b>Friday Game Night</b><small>{{demo.event.attended?'May 16, 2025 · Attended':demo.event.rsvp?'May 16, 2025 · Going':'May 16, 2025'}}</small></div><i>✓</i></li><li><span>🎙</span><div><b>Respawn Creator Q&amp;A</b><small>May 18, 2025 · Attended</small></div><i>✓</i></li></ul></article><article class="ccd-card"><h3>Rewards &amp; Cosmetics <small>View all</small></h3><ul class="media-list"><li><span>🌌</span><div><b>Neon Circuit Banner</b><small>Unlocked May 30, 2025</small></div><i>✓</i></li><li><span>♢</span><div><b>Community Regular Role</b><small>{{demo.achievement.unlocked?'Unlocked just now':'Progress '+demo.achievement.progress+' / 5'}}</small></div><i>{{demo.achievement.unlocked?'✓':'◷'}}</i></li></ul></article><article class="ccd-card achievement-progress"><h3>Achievement progress <small>View all</small></h3><div class="progress-ring"><strong>{{demo.nova.achievements}}<small>of 28</small></strong></div><b>{{Math.round(demo.nova.achievements/28*100)}}%</b><p>Achievements unlocked</p><div class="ccd-progress"><i :style="{width:demo.nova.achievements/28*100+'%'}"></i></div></article><article class="ccd-card status-card"><h3>♢ Moderation status</h3><strong class="ccd-positive">Good standing</strong><p>No active flags or restrictions.</p><small>Sensitive private notes are never displayed.</small></article><article class="ccd-card notes"><h3>▤ Connection &amp; data notes</h3><p>Identities are linked by the member. Data is aggregated from connected platforms and may not reflect all activity.</p><b class="ccd-purple">Learn more</b></article><article class="ccd-card"><h3>ⓘ Demo only</h3><p>All identities are fictional. No real connections, moderation actions, or financial attribution.</p></article></section></section></section></main></template>
<script setup>import{computed,ref}from'vue';import ConnectedDemoHeader from'../../connected-demo/ConnectedDemoHeader.vue';import{connectedDemo as demo,selectDemoMember}from'../../connected-demo/connectedDemoState.js';import'../../connected-demo/connectedDemo.css';const query=ref(''),filter=ref('All'),filters=['All','Connected','Twitch','Discord','Respawn','Supporters','Moderation review'];const members=[['member-nova','Nova#1234','Nova#1234','▣ ☁ R','Online','Bronze'],['pixel','PixelPanda','PixelPanda#5678','▣ ☁ R','Online','Silver'],['rogue','RogueFox','RogueFox#2468','▣ ☁','Idle','—'],['echo','EchoNova','EchoNova#3141','▣ ☁ R','Online','Gold'],['sparky','Sparky','Sparky#7788','☁ R','Offline','Bronze'],['kitsune','Kitsune','Kitsune#0001','▣ ☁','Offline','Silver'],['byte','ByteMage','ByteMage#1357','▣ R','Online','—'],['luna','LunaLight','LunaLight#8642','☁','Idle','Bronze']].map(([id,name,handle,platforms,status,tier])=>({id,name,handle,platforms,status,tier}));const shownMembers=computed(()=>members.filter(m=>(!query.value||m.name.toLowerCase().includes(query.value.toLowerCase()))&&(filter.value==='All'||filter.value==='Connected'&&m.platforms.split(' ').length>1||filter.value==='Twitch'&&m.platforms.includes('▣')||filter.value==='Discord'&&m.platforms.includes('☁')||filter.value==='Respawn'&&m.platforms.includes('R')||filter.value==='Supporters'&&m.tier!=='—'||filter.value==='Moderation review'&&false)));const selected=computed(()=>members.find(m=>m.id===demo.selectedMemberId)||members[0]);const selectedIdentities=computed(()=>selected.value.id==='member-nova'?demo.nova.identities:[{platform:'respawn',label:'Project Respawn',handle:selected.value.handle,authorised:true}]);function icon(id){return{id:'•',twitch:'▣',discord:'☁',respawn:'R'}[id]||'•'}</script>
<style scoped>.privacy-banner{margin-bottom:14px;padding:11px 14px;border:1px solid #1d3753;border-radius:7px;background:#0d2038;color:#aebbd0}.privacy-banner b{float:right;color:#c77cff}.members-layout{display:grid;grid-template-columns:410px minmax(0,1fr);gap:12px}.member-list{padding:0;overflow:hidden}.member-search{display:grid;grid-template-columns:1fr auto;gap:8px;padding:13px}.member-search input{width:100%;min-height:38px;box-sizing:border-box;padding:8px;border:1px solid #304660;border-radius:6px;background:#09162a;color:#fff}.member-head,.member-list>button{display:grid;grid-template-columns:42px 1fr 80px 80px 55px;align-items:center;gap:5px;width:100%;padding:10px;border:0;border-top:1px solid #1c3049;background:transparent;color:#e8eef8;text-align:left}.member-head{grid-template-columns:42px 1fr 80px 80px 55px;color:#95a4b8;font-size:11px}.member-head span:first-child{grid-column:1/3}.member-list>button{cursor:pointer}.member-list>button:hover,.member-list>button.active{background:#18193e;box-shadow:inset 3px 0 #a34be3}.avatar{display:grid;width:34px;height:34px;place-items:center;border:2px solid #8543c4;border-radius:50%;background:#39245f}.member-list>button small{display:block;color:#94a3b8}.platform-icons{color:#67d5ff}.status-idle{color:#eab34a}.member-list footer{display:flex;justify-content:space-between;padding:12px;color:#9ba9bd}.member-list footer button{min-width:30px;height:30px;border:0;border-radius:4px;background:#0d1b31;color:#c7d1df}.member-list footer button.active{background:#5d2aa4}.member-detail{display:grid;grid-template-columns:1fr 370px;gap:10px}.identity-card{display:grid;grid-template-columns:80px 1fr}.nova-avatar{display:grid;width:64px;height:64px;place-items:center;border:3px solid #9d4ae0;border-radius:50%;background:#3c205f;font-size:24px}.identity-card h2{display:inline;margin-right:10px;font-size:24px}.connected-pill{padding:5px 10px;border-radius:5px;background:#2a2053;color:#d48bff;font-size:11px}.identities{display:flex;gap:16px;margin-top:12px}.identities>span{display:grid;grid-template-columns:30px auto}.identities i{grid-row:1/3;display:grid;width:25px;height:25px;place-items:center;border-radius:5px;background:#26206a;font-style:normal}.identities small{color:#93a2b8}.privacy-cards{display:grid;grid-template-columns:1fr 1.4fr;padding:0}.privacy-cards article{padding:12px}.privacy-cards article+article{border-left:1px solid #243750}.confidence{display:grid;width:60px;height:60px;place-items:center;margin:auto;border:6px solid #58d4df;border-radius:50%;font-size:18px}.privacy-cards p{margin:7px 0;font-size:12px}.profile-tabs{grid-column:1/-1;display:flex;border-bottom:1px solid #30415a}.profile-tabs button{padding:10px 16px;border:0;background:transparent;color:#9ba9bd}.profile-tabs button.active{border-bottom:2px solid #b95af1;color:#d99bff}.member-metrics{grid-column:1/-1;display:grid;grid-template-columns:repeat(6,1fr);padding:0}.member-metrics article{display:grid;min-height:105px;padding:14px;border-right:1px solid #2c405a}.member-metrics article:last-child{border:0}.member-metrics article>span{font-size:22px}.member-metrics small{color:#9aa8bb}.member-metrics strong{font-size:22px}.member-metrics p{margin:0;color:#9daabd;font-size:11px}.member-detail-grid{grid-column:1/-1;display:grid;grid-template-columns:1.1fr 1fr 1fr 1fr;gap:10px}.timeline{grid-row:span 2}.ccd-card h3>small{float:right;color:#b56be8}.media-list{padding:0;list-style:none}.media-list li{display:grid;grid-template-columns:48px 1fr auto;align-items:center;gap:8px;padding:8px;border:1px solid #283d57;border-radius:6px;margin:7px 0}.media-list li>span{display:grid;width:42px;height:42px;place-items:center;border-radius:5px;background:#222257;font-size:22px}.media-list small{display:block;color:#92a2b8}.media-list i{color:#4ade80}.achievement-progress{display:grid;grid-template-columns:90px 1fr}.progress-ring{grid-row:2/5;display:grid;width:75px;height:75px;place-items:center;border:7px solid #8756df;border-radius:50%}.progress-ring small{display:block}.achievement-progress>.ccd-progress{grid-column:1/-1}.status-card{grid-column:2}.notes{grid-column:3/4}@media(max-width:1500px){.member-detail{grid-template-columns:1fr}.privacy-cards{grid-column:1}.member-detail-grid{grid-template-columns:1fr 1fr 1fr}.timeline{grid-row:auto}.status-card,.notes{grid-column:auto}}@media(max-width:1100px){.members-layout{grid-template-columns:1fr}.member-list{max-height:520px;overflow:auto}.member-metrics{grid-template-columns:repeat(3,1fr)}.member-detail-grid{grid-template-columns:1fr 1fr}}@media(max-width:700px){.member-detail-grid,.privacy-cards{grid-template-columns:1fr}.member-metrics{grid-template-columns:1fr 1fr}.identities{display:grid}.member-list>button,.member-head{grid-template-columns:42px 1fr 65px}.member-list>button>*:nth-last-child(-n+2),.member-head>*:nth-last-child(-n+2){display:none}.profile-tabs{overflow:auto}}</style>
